/**
 * Reading the pieces we need out of YouTube's ytInitialPlayerResponse and ytInitialData.
 *
 * Every function here is defensive. These are undocumented internal structures that
 * change without notice, so a missing node returns null or undefined rather than
 * throwing. Chapters in particular are optional: a video without them must still parse.
 */

import type { Chapter } from './types.ts';

export interface CaptionTrack {
  baseUrl: string;
  languageCode: string;
  /** 'asr' means auto-generated. Absent means manually created. */
  kind?: string;
  name?: { simpleText?: string; runs?: Array<{ text?: string }> };
  vssId?: string;
}

export interface VideoDetails {
  videoId: string | null;
  durationSec: number | null;
}

/** Safe nested property access over an unknown JSON blob. */
function dig(root: unknown, ...keys: Array<string | number>): unknown {
  let node: unknown = root;
  for (const key of keys) {
    if (node === null || typeof node !== 'object') return undefined;
    node = (node as Record<string | number, unknown>)[key];
  }
  return node;
}

function asArray(value: unknown): unknown[] {
  return Array.isArray(value) ? value : [];
}

/** YouTube writes text nodes as either { simpleText } or { runs: [{ text }] }. */
function readText(value: unknown): string | null {
  const simple = dig(value, 'simpleText');
  if (typeof simple === 'string' && simple.trim()) return simple.trim();

  const runs = asArray(dig(value, 'runs'))
    .map((run) => dig(run, 'text'))
    .filter((text): text is string => typeof text === 'string')
    .join('');
  return runs.trim() || null;
}

export function getCaptionTracks(playerResponse: unknown): CaptionTrack[] {
  const tracks = asArray(
    dig(playerResponse, 'captions', 'playerCaptionsTracklistRenderer', 'captionTracks'),
  );

  return tracks.flatMap((raw) => {
    const baseUrl = dig(raw, 'baseUrl');
    const languageCode = dig(raw, 'languageCode');
    if (typeof baseUrl !== 'string' || !baseUrl) return [];

    const kind = dig(raw, 'kind');
    const vssId = dig(raw, 'vssId');
    const track: CaptionTrack = {
      baseUrl,
      languageCode: typeof languageCode === 'string' ? languageCode : '',
    };
    if (typeof kind === 'string') track.kind = kind;
    if (typeof vssId === 'string') track.vssId = vssId;
    const name = dig(raw, 'name');
    if (name && typeof name === 'object') track.name = name as NonNullable<CaptionTrack['name']>;
    return [track];
  });
}

export function isAutoGenerated(track: CaptionTrack): boolean {
  return track.kind === 'asr' || track.vssId?.startsWith('a.') === true;
}

/** 'en-GB' and 'en' both reduce to 'en'. */
function baseLanguage(code: string): string {
  return code.toLowerCase().split(/[-_]/)[0] ?? '';
}

/**
 * Lower is better. Manual tracks always beat auto-generated ones, and within each group
 * an exact language match beats a base-language match beats no match at all.
 */
function trackRank(track: CaptionTrack, preferredLangs: readonly string[]): number {
  const code = track.languageCode.toLowerCase();
  const base = baseLanguage(code);

  let langRank = 90;
  for (let i = 0; i < preferredLangs.length; i += 1) {
    const preferred = preferredLangs[i]!.toLowerCase();
    if (code === preferred) {
      langRank = Math.min(langRank, i);
      break;
    }
    if (base === baseLanguage(preferred)) {
      langRank = Math.min(langRank, 40 + i);
    }
  }

  return (isAutoGenerated(track) ? 1000 : 0) + langRank;
}

/**
 * Picks the best caption track: manual in the preferred language, then manual in any
 * language, then auto-generated in the preferred language, then auto-generated in any.
 * Returns null for an empty list, which the caller turns into a typed no-captions failure.
 */
export function selectCaptionTrack(
  tracks: readonly CaptionTrack[],
  preferredLangs: readonly string[] = ['en'],
): CaptionTrack | null {
  let best: CaptionTrack | null = null;
  let bestRank = Number.POSITIVE_INFINITY;

  for (const track of tracks) {
    const rank = trackRank(track, preferredLangs);
    if (rank < bestRank) {
      best = track;
      bestRank = rank;
    }
  }

  return best;
}

/**
 * Sets the format parameter on a caption track URL without disturbing anything else.
 *
 * This deliberately does not use URL.searchParams. Assigning any parameter re-serializes
 * the whole query string, which re-encodes characters YouTube left literal: sparams is a
 * comma-separated list, and turning those commas into %2C invalidates the signature the
 * URL carries. The request then returns empty and the video looks like it has no captions
 * at all. String surgery keeps the signed portion byte for byte.
 */
export function withCaptionFormat(baseUrl: string, fmt: string | null): string {
  const stripped = baseUrl.replace(/([?&])fmt=[^&]*/g, (_match, separator: string) =>
    separator === '?' ? '?' : '',
  );
  const cleaned = stripped.replace(/\?&/, '?').replace(/[?&]$/, '');
  if (fmt === null) return cleaned;
  return `${cleaned}${cleaned.includes('?') ? '&' : '?'}fmt=${fmt}`;
}

/**
 * Adds the client tag and proof-of-origin token that /api/timedtext requires.
 *
 * Both are needed together. A signed URL with neither, or with only one of the two,
 * returns HTTP 200 and an empty body, which is indistinguishable from a video that has no
 * captions. See content/pot.ts for where the token comes from.
 *
 * A null token leaves the URL alone rather than sending an empty parameter, so the caller
 * still gets to try the request and record what came back.
 */
export function withProofOfOrigin(url: string, pot: string | null): string {
  if (pot === null || pot === '') return url;
  const separator = url.includes('?') ? '&' : '?';
  return `${url}${separator}c=WEB&pot=${encodeURIComponent(pot)}`;
}

export function getVideoDetails(playerResponse: unknown): VideoDetails {
  const videoId = dig(playerResponse, 'videoDetails', 'videoId');
  const lengthSeconds = dig(playerResponse, 'videoDetails', 'lengthSeconds');
  const parsed = typeof lengthSeconds === 'string' ? Number(lengthSeconds) : lengthSeconds;

  return {
    videoId: typeof videoId === 'string' && videoId ? videoId : null,
    durationSec: typeof parsed === 'number' && Number.isFinite(parsed) && parsed > 0 ? parsed : null,
  };
}

/** Depth-limited search for the first object carrying `key`. */
function findByKey(root: unknown, key: string, maxDepth = 12): unknown {
  const queue: Array<{ node: unknown; depth: number }> = [{ node: root, depth: 0 }];

  while (queue.length > 0) {
    const { node, depth } = queue.shift()!;
    if (node === null || typeof node !== 'object' || depth > maxDepth) continue;

    if (!Array.isArray(node) && key in (node as Record<string, unknown>)) {
      return (node as Record<string, unknown>)[key];
    }
    for (const value of Object.values(node as Record<string, unknown>)) {
      if (value !== null && typeof value === 'object') {
        queue.push({ node: value, depth: depth + 1 });
      }
    }
  }

  return undefined;
}

function chaptersFromMarkersMap(markersMap: unknown): Chapter[] {
  const preferredKeys = ['DESCRIPTION_CHAPTERS', 'AUTO_CHAPTERS'];
  const entries = asArray(markersMap);

  const ordered = [
    ...entries.filter((entry) => preferredKeys.includes(String(dig(entry, 'key')))),
    ...entries.filter((entry) => !preferredKeys.includes(String(dig(entry, 'key')))),
  ];

  for (const entry of ordered) {
    const chapters = asArray(dig(entry, 'value', 'chapters')).flatMap((raw) => {
      const renderer = dig(raw, 'chapterRenderer');
      const title = readText(dig(renderer, 'title'));
      const startMs = dig(renderer, 'timeRangeStartMillis');
      if (title === null || typeof startMs !== 'number' || !Number.isFinite(startMs)) return [];
      return [{ title, start: startMs / 1000 }];
    });
    if (chapters.length > 0) return chapters;
  }

  return [];
}

function chaptersFromMacroMarkers(root: unknown): Chapter[] {
  const renderer = findByKey(root, 'macroMarkersListRenderer');
  return asArray(dig(renderer, 'contents')).flatMap((raw) => {
    const renderer = dig(raw, 'macroMarkersListItemRenderer');
    const title = readText(dig(renderer, 'title'));
    const startSec = dig(renderer, 'onTap', 'watchEndpoint', 'startTimeSeconds');
    if (title === null || typeof startSec !== 'number' || !Number.isFinite(startSec)) return [];
    return [{ title, start: startSec }];
  });
}

/**
 * Chapters from ytInitialData, if the video has any. Never throws: a missing chapter
 * list is a normal outcome and must not fail the surrounding parse.
 */
export function extractChapters(ytInitialData: unknown): Chapter[] | undefined {
  if (ytInitialData === null || typeof ytInitialData !== 'object') return undefined;

  let chapters: Chapter[] = [];
  try {
    const knownPath = dig(
      ytInitialData,
      'playerOverlays',
      'playerOverlayRenderer',
      'decoratedPlayerBarRenderer',
      'decoratedPlayerBarRenderer',
      'playerBar',
      'multiMarkersPlayerBarRenderer',
      'markersMap',
    );

    chapters = chaptersFromMarkersMap(knownPath);
    if (chapters.length === 0) {
      chapters = chaptersFromMarkersMap(findByKey(ytInitialData, 'markersMap'));
    }
    if (chapters.length === 0) {
      chapters = chaptersFromMacroMarkers(ytInitialData);
    }
  } catch {
    return undefined;
  }

  const cleaned = chapters
    .filter((chapter) => chapter.start >= 0)
    .sort((a, b) => a.start - b.start)
    .filter((chapter, i, all) => i === 0 || chapter.start !== all[i - 1]!.start);

  return cleaned.length > 0 ? cleaned : undefined;
}
